public with sharing class OrderSummary {
  @AuraEnabled public String orderNumber { get; set; }
  @AuraEnabled public Decimal total { get; set; }
  public String status { get; set; }
}

public with sharing class OrderDashboardController {
  @AuraEnabled(cacheable=true)
  public static List<OrderSummary> getSummaries(Id accountId) {
    List<OrderSummary> rows = new List<OrderSummary>();
    for (Order o : [SELECT OrderNumber, TotalAmount, Status
                    FROM Order WHERE AccountId = :accountId]) {
      OrderSummary s = new OrderSummary();
      s.orderNumber = o.OrderNumber;
      s.total = o.TotalAmount;
      s.status = o.Status;
      rows.add(s);
    }
    return rows;
  }
}

